import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';
import { Buffer } from 'buffer';

const app = express();
app.use(express.raw({ type: '*/*', limit: '10mb' }));

const SERVICE_KEYS: Record<string, string> = {
  'model-trainer': 'k8s-internal-2f8a9c3d',
  'data-pipeline': 'k8s-internal-7e1b4f6a',
  'api-gateway': 'k8s-internal-9d3c8e2b'
};

const ALLOWED_MODEL_PATHS = ['/models/prod/', '/models/staging/'];

interface InferenceRequest {
  model_path: string;
  input_tensor: number[][];
  options?: { batch_size?: number; timeout_ms?: number };
}

function constantTimeCompare(a: Buffer, b: Buffer): boolean {
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

function verifyServiceSignature(serviceId: string, timestamp: string, payload: Buffer, signature: string): boolean {
  const key = SERVICE_KEYS[serviceId];
  if (!key) return false;

  const timestampNum = parseInt(timestamp, 10);
  if (!Number.isFinite(timestampNum)) return false;
  const now = Date.now();
  if (Math.abs(now - timestampNum) > 30000) return false;

  const hmac = crypto.createHmac('sha256', key);
  hmac.update(timestamp);
  hmac.update('.');
  hmac.update(payload);
  const expected = Buffer.from(hmac.digest('hex'), 'utf8');
  const provided = Buffer.from(signature, 'utf8');

  return constantTimeCompare(expected, provided);
}

function normalizeModelPath(rawPath: string): string {
  const decoded = decodeURIComponent(rawPath);
  const normalized = decoded.replace(/\\/g, '/');
  const segments = normalized.split('/');
  const resolved: string[] = [];

  for (const seg of segments) {
    if (seg === '..') {
      resolved.pop();
    } else if (seg !== '.' && seg !== '') {
      resolved.push(seg);
    }
  }

  return '/' + resolved.join('/');
}

function validateModelPath(modelPath: string): boolean {
  const normalized = normalizeModelPath(modelPath);
  return ALLOWED_MODEL_PATHS.some(allowed => normalized.startsWith(allowed));
}

function parseRequestBody(payload: Buffer): InferenceRequest {
  const text = payload.toString('utf8');
  const parsed = JSON.parse(text);

  if (!parsed.model_path || !Array.isArray(parsed.input_tensor)) {
    throw new Error('Invalid inference request format');
  }

  return parsed as InferenceRequest;
}

async function runInference(req: InferenceRequest): Promise<{ predictions: number[]; latency_ms: number }> {
  const start = Date.now();
  // Simulated inference
  const predictions = req.input_tensor.map(row => 
    row.reduce((sum, val) => sum + val * 0.1, 0)
  );
  return { predictions, latency_ms: Date.now() - start };
}

function authMiddleware(req: Request, res: Response, next: NextFunction): void {
  const serviceId = req.headers['x-service-id'] as string;
  const timestamp = req.headers['x-timestamp'] as string;
  const signature = req.headers['x-signature'] as string;

  if (!serviceId || !timestamp || !signature) {
    res.status(401).json({ error: 'Missing authentication headers' });
    return;
  }

  const payload = req.body as Buffer;
  if (!verifyServiceSignature(serviceId, timestamp, payload, signature)) {
    res.status(403).json({ error: 'Invalid signature' });
    return;
  }

  next();
}

app.post('/v1/inference', authMiddleware, async (req: Request, res: Response) => {
  try {
    const payload = req.body as Buffer;
    const inferenceReq = parseRequestBody(payload);

    if (!validateModelPath(inferenceReq.model_path)) {
      res.status(400).json({ error: 'Model path not in allowed list' });
      return;
    }

    const result = await runInference(inferenceReq);
    res.json({ status: 'success', ...result });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/v1/admin/reload-model', authMiddleware, async (req: Request, res: Response) => {
  try {
    const payload = req.body as Buffer;
    const text = payload.toString('utf8');
    const { model_path } = JSON.parse(text);

    // Admin endpoint validates and uses the normalized path
    const normalizedPath = normalizeModelPath(model_path);
    if (!ALLOWED_MODEL_PATHS.some(allowed => normalizedPath.startsWith(allowed))) {
      res.status(400).json({ error: 'Invalid model path' });
      return;
    }

    // Use the normalized path for the file system operation
    const resolvedPath = `/opt/ml${normalizedPath}`;

    res.json({ status: 'reloaded', path: resolvedPath });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

app.listen(8080, () => console.log('ML Inference server on :8080'));

export default app;
